    Fig.text(ctx, `A ${Math.round(pa * 100)}%`, ax - ra * 0.4, cy - ra * 0.5, th.fg, 13, 'center', 'middle', true); Fig.text(ctx, `B ${Math.round(pb * 100)}%`, bx + rb * 0.4, cy - rb * 0.5, th.fg, 13, 'center', 'middle', true); Fig.text(ctx, `A∩B ${Math.round(pab * 100)}%`, (ax + bx) / 2, cy + 2, th.fg, 12, 'center', 'middle', true);
