// ===================== 운영체제 교과서 그림 (v2.23.1, specs/os-course.md 3절 — 눈으로 보기 어려운 것만) =====================
// CPU 스케줄링 간트 차트: 같은 작업들을 FCFS · SJF(비선점) · 라운드 로빈(q) 세 줄로. f.jobs:[{n, at(도착), bt(실행 시간)}] · p:{q}
Fig.sched = {
  fcfs(jobs) { const js = jobs.map((j, i) => ({ ...j, i })).sort((a, b) => a.at - b.at || a.i - b.i); const seg = []; let t = 0; for (const j of js) { if (t < j.at) t = j.at; seg.push([j.n, t, t + j.bt]); t += j.bt; } return seg; },
  sjf(jobs) { const left = jobs.map((j, i) => ({ ...j, i })); const seg = []; let t = 0; while (left.length) { const ready = left.filter(j => j.at <= t); if (!ready.length) { t = Math.min(...left.map(j => j.at)); continue; } ready.sort((a, b) => a.bt - b.bt || a.at - b.at || a.i - b.i); const j = ready[0]; seg.push([j.n, t, t + j.bt]); t += j.bt; left.splice(left.indexOf(j), 1); } return seg; },
  rr(jobs, q) { const js = jobs.map((j, i) => ({ ...j, i, rem: j.bt })).sort((a, b) => a.at - b.at || a.i - b.i); const seg = []; const queue = []; let t = 0, k = 0; const arrive = (until) => { while (k < js.length && js[k].at <= until) queue.push(js[k++]); };
    arrive(t); while (queue.length || k < js.length) { if (!queue.length) { t = js[k].at; arrive(t); continue; } const j = queue.shift(); const run = Math.min(q, j.rem); const last = seg[seg.length - 1]; if (last && last[0] === j.n && last[2] === t) last[2] = t + run; else seg.push([j.n, t, t + run]); t += run; j.rem -= run; arrive(t); if (j.rem > 0) queue.push(j); } return seg; },
  wait(jobs, seg) { const end = {}; seg.forEach(([n, , e]) => { end[n] = Math.max(end[n] || 0, e); }); const w = jobs.map(j => end[j.n] - j.at - j.bt); return w.reduce((a, b) => a + b, 0) / jobs.length; },
};
Fig.kinds.gantt = { draw(ctx, W, H, p, f, th) { const jobs = f.jobs; const q = Math.max(1, Math.round(p.q || 2)); const rows = [['먼저 온 순 (FCFS)', Fig.sched.fcfs(jobs)], ['짧은 것 먼저 (SJF)', Fig.sched.sjf(jobs)], [`번갈아 (RR, q=${q})`, Fig.sched.rr(jobs, q)]];
    const T = Math.max(...rows.map(r => r[1][r[1].length - 1][2])); const narrow = W < 480; const x0 = narrow ? 12 : 150, x1 = W - 14; const rowH = (H - 34) / 3; const sx = (x1 - x0) / T; const col = {}; jobs.forEach((j, i) => { col[j.n] = Fig.palette[i % 5]; });
    rows.forEach(([name, seg], r) => { const y = 8 + r * rowH; const by = narrow ? y + 18 : y + 6; const bh = Math.min(26, rowH - (narrow ? 26 : 14)); const avg = Fig.sched.wait(jobs, seg);
      Fig.text(ctx, name, narrow ? x0 : 10, narrow ? y + 8 : by + bh / 2, th.fg, 12, 'left', 'middle', true); Fig.text(ctx, `평균 대기 ${Fig.fmt(avg, 2)}`, x1, narrow ? y + 8 : by + bh + 9, th.muted, 11, 'right', 'middle');
      ctx.strokeStyle = th.border; ctx.strokeRect(x0, by, x1 - x0, bh);
      seg.forEach(([n, s, e]) => { const a = x0 + s * sx, w = (e - s) * sx; ctx.fillStyle = col[n]; ctx.fillRect(a + 1, by + 1, w - 2, bh - 2); if (w > 12) Fig.text(ctx, n, a + w / 2, by + bh / 2, '#fff', 12, 'center', 'middle', true); }); });
    const step = T > 16 ? 2 : 1; for (let t = 0; t <= T; t += step) Fig.text(ctx, String(t), x0 + t * sx, H - 12, th.muted, 10, 'center');
    return `작업 ${jobs.map(j => `${j.n}(${j.at}에 와서 ${j.bt})`).join(' · ')} — 대기 = 끝난 시각 − 온 시각 − 실행 시간`; } };
// 교착 상태: 일꾼 둘(T1·T2) · 락 둘(A·B). p:{same(0 반대 순서 / 1 같은 순서)} · 버튼으로 한 걸음씩. 굵은 실선 = 쥐고 있음, 점선 = 기다림
Fig.deadlockSteps = {
  0: [['', '', '', '', '처음: 아무도 락을 안 쥐었어요'], ['A', '', '', '', 'T1 이 A 를 잡았어요'], ['A', 'B', '', '', 'T2 가 B 를 잡았어요(반대 순서라서 B 부터)'], ['A', 'B', 'B', '', 'T1 이 B 를 기다려요 — B 는 T2 가 쥐고 있어요'], ['A', 'B', 'B', 'A', '교착! T2 는 A 를, T1 은 B 를 기다려요 — 서로 놓기를 기다리며 영원히 멈춰요']],
  1: [['', '', '', '', '처음: 아무도 락을 안 쥐었어요'], ['A', '', '', '', 'T1 이 A 를 잡았어요'], ['A', '', '', 'A', 'T2 도 A 부터 — A 를 기다려요(B 는 아직 아무도 안 쥠)'], ['AB', '', '', 'A', 'T1 이 B 까지 잡고 일해요'], ['', 'AB', '', '', 'T1 이 둘 다 놓자 T2 가 A·B 를 잡아요 — 둘 다 끝까지 가요']],
};
Fig.kinds.deadlock = { defaultButtons: () => [{ label: '한 걸음', act: (st) => { st.k = Math.min(4, st.k + 1); } }, { label: '처음', act: (st) => { st.k = 0; } }], init(st) { st.k = 0; }, onParams(st) { st.k = 0; },
  draw(ctx, W, H, p, f, th, st) { const same = Math.round(p.same || 0) ? 1 : 0; const [h1, h2, w1, w2, msg] = Fig.deadlockSteps[same][st.k]; const cy = H / 2 - 10; const tx = [W * 0.16, W * 0.84], lx = W / 2, ly = { A: cy - 46, B: cy + 46 };
    const box = (x, label, color) => { ctx.fillStyle = th.surface2; ctx.strokeStyle = color; ctx.lineWidth = 2; ctx.beginPath(); ctx.roundRect ? ctx.roundRect(x - 38, cy - 22, 76, 44, 10) : ctx.rect(x - 38, cy - 22, 76, 44); ctx.fill(); ctx.stroke(); Fig.text(ctx, label, x, cy, th.fg, 15, 'center', 'middle', true); };
    const line = (x, L, color, dashed) => { ctx.save(); ctx.strokeStyle = color; ctx.lineWidth = dashed ? 2 : 4; ctx.setLineDash(dashed ? [6, 5] : []); ctx.beginPath(); ctx.moveTo(x + (x < lx ? 38 : -38), cy); ctx.lineTo(lx + (x < lx ? -16 : 16), ly[L]); ctx.stroke(); ctx.restore(); };
    [[tx[0], h1, w1, Fig.palette[0]], [tx[1], h2, w2, Fig.palette[1]]].forEach(([x, held, wait, c]) => { [...held].forEach(L => line(x, L, c, false)); [...wait].forEach(L => line(x, L, c, true)); });
    box(tx[0], 'T1', Fig.palette[0]); box(tx[1], 'T2', Fig.palette[1]);
    ['A', 'B'].forEach(L => { const holder = h1.includes(L) ? Fig.palette[0] : h2.includes(L) ? Fig.palette[1] : th.border; Fig.dot(ctx, lx, ly[L], 16, th.bg, holder); Fig.text(ctx, '락 ' + L, lx, ly[L], th.fg, 12, 'center', 'middle', true); });
    const dead = !same && st.k === 4; Fig.text(ctx, `${st.k} / 4 · ${same ? '같은 순서(A → B)' : '반대 순서(T1: A → B, T2: B → A)'}`, W / 2, 12, th.muted, 11, 'center'); const mc = dead ? th.danger : th.fg; const parts = W < 480 ? msg.split(' — ') : [msg]; parts.forEach((m, i) => Fig.text(ctx, m, W / 2, H - 14 - (parts.length - 1 - i) * 17, mc, W < 480 ? 12 : 13, 'center', 'middle', true)); /* 폰: 「 — 」 에서 두 줄로 */
    return '굵은 선 = 쥐고 있음 · 점선 = 기다림'; } };
// 페이지 교체 표(v2.23.2): 위 = 참조 순서, 아래 = 프레임마다 든 페이지, 폴트 난 칸은 색칠. p:{algo(0 FIFO · 1 LRU · 2 OPT), frames, set(0 교과서 예 · 1 벨라디 예)}
Fig.pageRefs = [[7, 0, 1, 2, 0, 3, 0, 4, 2, 3, 0, 3, 2, 1, 2, 0, 1, 7, 0, 1], [1, 2, 3, 4, 1, 2, 5, 1, 2, 3, 4, 5]];
Fig.pageReplace = (ref, n, algo) => { const slots = Array(n).fill(null); const born = Array(n).fill(0), used = Array(n).fill(0); const steps = []; let faults = 0;
  ref.forEach((pg, t) => { let k = slots.indexOf(pg); let fault = false;
    if (k < 0) { fault = true; faults++; k = slots.indexOf(null);
      if (k < 0) { if (algo === 0) k = born.indexOf(Math.min(...born)); else if (algo === 1) k = used.indexOf(Math.min(...used)); else { const next = slots.map(s => { const j = ref.indexOf(s, t + 1); return j < 0 ? Infinity : j; }); k = next.indexOf(Math.max(...next)); } }
      slots[k] = pg; born[k] = t + 1; }
    used[k] = t + 1; steps.push({ slots: [...slots], k, fault }); });
  return { steps, faults }; };
Fig.kinds.pagereplace = { draw(ctx, W, H, p, f, th) { const ref = Fig.pageRefs[Math.round(p.set || 0) ? 1 : 0]; const n = Math.max(1, Math.round(p.frames || 3)); const algo = Math.max(0, Math.min(2, Math.round(p.algo || 0))); const names = ['FIFO(먼저 들어온 것)', 'LRU(가장 오래 안 쓴 것)', 'OPT(가장 늦게 쓸 것 — 비교용)'];
    const { steps, faults } = Fig.pageReplace(ref, n, algo); const all = [0, 1, 2].map(a => Fig.pageReplace(ref, n, a).faults);
    const x0 = W < 480 ? 34 : 70, x1 = W - 8; const cw = (x1 - x0) / ref.length; const top = 30; const ch = Math.min(26, (H - top - 56) / (n + 1)); const fs = cw < 18 ? 10 : 12;
    Fig.text(ctx, `${names[algo]} · 프레임 ${n}개 → 폴트 ${faults}번`, 8, 12, th.fg, W < 480 ? 11 : 13, 'left', 'middle', true);
    Fig.text(ctx, '참조', x0 - 6, top + ch / 2, th.muted, 10, 'right');
    ref.forEach((pg, t) => { const x = x0 + t * cw; Fig.text(ctx, String(pg), x + cw / 2, top + ch / 2, th.fg, fs, 'center', 'middle', true);
      const s = steps[t]; for (let r = 0; r < n; r++) { const y = top + ch * (r + 1) + 4; const v = s.slots[r]; const hit = s.fault && r === s.k; ctx.fillStyle = hit ? Fig.palette[1] + 'cc' : th.surface2; ctx.fillRect(x + 1, y, cw - 2, ch - 2); if (v != null) Fig.text(ctx, String(v), x + cw / 2, y + (ch - 2) / 2, hit ? '#fff' : th.muted, fs, 'center', 'middle', hit); }
      if (s.fault) Fig.text(ctx, 'F', x + cw / 2, top + ch * (n + 1) + 14, Fig.palette[1], 10, 'center', 'middle', true); });
    for (let r = 0; r < n; r++) Fig.text(ctx, W < 480 ? `${r + 1}` : `프레임 ${r + 1}`, x0 - 6, top + ch * (r + 1) + 4 + (ch - 2) / 2, th.muted, 10, 'right');
    Fig.text(ctx, `같은 프레임 수에서 — FIFO ${all[0]} · LRU ${all[1]} · OPT ${all[2]}`, 8, Math.min(H - 10, top + ch * (n + 1) + 38), th.fg, 12, 'left', 'middle', true);
    return '빨간 칸 = 페이지 폴트(그 칸에 새로 들어옴) · F 줄 = 폴트 난 차례'; } };
